import sys; sys.path.insert(0,'.')
from cvlib import folds
from scipy.special import erf
gelu=lambda x: 0.5*x*(1+erf(x/np.sqrt(2)))
d=np.load('base_reads.npz'); y=d['y']; R=np.load('reserved.npy')
keep=np.setdiff1d(np.arange(768),R)
M={j:d[f'mean_hidden_L{j}'][:,keep] for j in range(13)}; C12=d['cls_hidden_L12'][:,keep]
def z(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def kpred(K, lam, s):
    Y=np.eye(8)[y]; f=folds(y,5,s); S=np.zeros((len(y),8))
    for i in range(5):
        tr=f!=i; te=f==i
        A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0))
        S[te]=K[np.ix_(te,tr)]@A
    return S.argmax(1)
Xs=z(np.hstack([M[2],M[6],M[10],C12])); Ks=Xs@Xs.T
L26=z(M[2])@z(M[2]).T/760+z(M[6])@z(M[6]).T/760
cand={}
for top in (8,9):
    Z=z(M[top]); cand[top]=2*gelu(Z@Z.T/760)+L26
seeds=range(6)
res={8:[],9:[]}
for s in seeds:
    ps=kpred(Ks,300,s)
    for top in (8,9):
        pc=kpred(cand[top],0.03,s)
        res[top].append(((ps!=y).sum(),(pc!=y).sum(),((pc!=y)&(ps==y)).sum(),((ps!=y)&(pc==y)).sum()))
for top in (8,9):
    a=np.array(res[top]); print(top,'start err',a[:,0].mean(),'cand err',a[:,1].mean(),'cand-only',a[:,2].mean(),'start-only',a[:,3].mean())
# risk simulation: test start errors fixed at 98.31%; candidate extra = Pois(pc*N) - Binomial among start errors(ps_rate)
rng=np.random.RandomState(0)
for top in (8,9):
    a=np.array(res[top]).mean(0); n=1496
    for N in (592,1184):
        e_s=round((1-0.9831)*N)
        co=rng.poisson(a[2]/n*N,200000)          # cand wrong where start right
        so=rng.binomial(e_s, a[3]/a[0], 200000)   # start errors cand fixes
        e_c=e_s+co-so; acc=1-e_c/N
        print(top,N,'mean acc %.4f  P(fail<97.8)=%.3f'%(acc.mean(),(acc<0.978).mean()))
